<?php $select=function($name,$label,$rows)use($filters){?><div class="col-md-4 col-xl-3"><label class="form-label" for="<?=$name?>"><?=html_escape($label)?></label><select class="form-select" id="<?=$name?>" name="<?=$name?>"><option value="">All</option><?php foreach($rows as$row):?><option value="<?=html_escape($row->option_id)?>" <?=(string)$filters[$name]===(string)$row->option_id?'selected':''?>><?=html_escape($row->option_label)?></option><?php endforeach;?></select></div><?php }; ?>
